24	// Triggers — issue comments, PR comments, PR-ready transitions
25	// ---------------------------------------------------------------------------
26	
27	const TRIGGERS = [
28	  { test: cmd => cmd.includes('gh issue comment'), type: 'issue_comment' },
29	  { test: cmd => cmd.includes('gh pr comment'),    type: 'pr_comment'   },
30	  { test: cmd => /\bgh pr ready\b/.test(cmd),      type: 'pr_ready'     },
