33	async function run(raw) {
34	  if (!SLACK_TOKEN) { process.stderr.write('slack-notify: SLACK_BOT_TOKEN not set\n'); return; }
35	
36	  let data;
37	  try { data = JSON.parse(raw); } catch { return; }
