39	  if (data.tool_name !== 'Bash') return;
40	  const command = data.tool_input?.command || '';
41	  const trigger = TRIGGERS.find(t => t.test(command));
42	  if (!trigger) return;
43	
44	  const output = getOutput(data);
45	
46	  if (trigger.type === 'pr_ready') {
47	    await handlePrReady(command, output);
48	    return;
49	  }
50	
51	  // Require a GitHub URL in the output confirming the comment was posted
52	  const commentUrlMatch =
53	    output.match(/https:\/\/github\.com\/[^\s<>]+#issuecomment-\d+/) ||
54	    output.match(/https:\/\/github\.com\/[^\s<>]+#discussion_r\d+/);
55	  if (!commentUrlMatch) {
56	    process.stderr.write('slack-notify: no comment URL in gh output — command may have failed\n');
57	    return;
58	  }
59	  const commentUrl = commentUrlMatch[0];
60	
61	  const isIssue  = trigger.type === 'issue_comment';
62	  const refMatch = command.match(/gh (?:issue|pr) comment\s+([^\s"'\\]+)/);
63	  const refNum   = refMatch?.[1]?.match(/\d+/)?.[0] || '';
64	  const ghUrl    = isIssue
65	    ? `https://github.com/wp-media/wp-rocket/issues/${refNum}`
66	    : `https://github.com/wp-media/wp-rocket/pull/${refNum}`;
67	
68	  const body        = extractBody(command);
69	  const commentType = detectCommentType(body);
70	
71	  // For PR comments, try to extract the associated issue number for threading
72	  const issueNum = isIssue ? refNum : (extractIssueFromBody(body) || '');
73	
74	  const { text, blocks } = buildMessage(commentType, body, refNum, ghUrl, commentUrl, isIssue);
75	
76	  // Thread all events for the same issue together
77	  const threadTs = issueNum ? getThreadTs(issueNum) : null;
78	  const payload  = { channel: CHANNEL_ID, text, blocks };
79	  if (threadTs) payload.thread_ts = threadTs;
80	
81	  const postedTs = await postToSlack(payload);
82	  if (!threadTs && issueNum && postedTs) saveThreadTs(issueNum, postedTs);
83	}
