110	// ---------------------------------------------------------------------------
111	// Comment type detection
112	// ---------------------------------------------------------------------------
113	
114	function detectCommentType(body) {
115	  const h = (body.match(/^#{1,3}\s+(.+)$/m)?.[1] || '').toLowerCase();
116	  if (h.includes('delivery pipeline') || h.includes('pipeline — complete') || h.includes('pipeline complete')) return 'pipeline_summary';
117	  if (h.includes('groomin'))                                                                                    return 'grooming';
118	  if (h.includes('challenger') || h.includes('spec review'))                                                   return 'challenger';
119	  if (h.includes('implementation') || h.includes('dev complete'))                                              return 'implementation';
120	  if (h.includes('lead review') || h.includes('code review') || h.includes('pr review'))                      return 'lead_review';
121	  if (/ qa\b/.test(h) || h.includes('quality assurance') || h.includes('test report'))                        return 'qa';
122	  return 'generic';
123	}
