125	// ---------------------------------------------------------------------------
126	// Message builder
127	// ---------------------------------------------------------------------------
128	
129	function buildMessage(commentType, body, num, ghUrl, commentUrl, isIssue) {
130	  switch (commentType) {
131	    case 'pipeline_summary': return buildPipelineSummary(body, num, ghUrl, commentUrl);
132	    case 'grooming':         return buildStageCard('🔍', 'Grooming complete',   body, num, ghUrl, commentUrl, isIssue, buildGroomingDetail);
133	    case 'challenger':       return buildStageCard('⚔️',  'Spec Review',         body, num, ghUrl, commentUrl, isIssue, buildChallengerDetail);
134	    case 'implementation':   return buildStageCard('⚙️',  'Implementation',      body, num, ghUrl, commentUrl, isIssue, null);
135	    case 'lead_review':      return buildStageCard('👀', 'Lead Review',          body, num, ghUrl, commentUrl, isIssue, buildReviewDetail);
136	    case 'qa':               return buildStageCard('🧪', 'QA Report',            body, num, ghUrl, commentUrl, isIssue, buildQADetail);
137	    default:                 return buildGenericCard(body, num, ghUrl, commentUrl, isIssue);
138	  }
139	}
