141	// ---------------------------------------------------------------------------
142	// Pipeline summary — header + markdown table of stages
143	// ---------------------------------------------------------------------------
144	
145	function buildPipelineSummary(body, issueNum, issueUrl, commentUrl) {
146	  const title = body.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() || 'Delivery Pipeline — Complete';
147	
148	  const prMatch     = body.match(/\*\*PR:\*\*\s*\[#(\d+)\]\(([^)]+)\)/);
149	  const statusMatch = body.match(/\*\*Status:\*\*\s*([^\n|*]+)/);
150	  const prNum   = prMatch?.[1];
151	  const prUrl   = prMatch?.[2];
152	  const status  = statusMatch?.[1]?.trim() || 'READY FOR REVIEW';
153	  const isReady = status.includes('READY');
154	
155	  // Build the markdown table from the stage table in the comment body
156	  const tableRows  = parseMarkdownTable(body);
157	  const tableLines = [
158	    '| Stage | Status | Notes |',
159	    '|---|---|---|',
160	    ...tableRows.map(([stage = '', result = '', notes = '']) => {
161	      const notesClean = (notes && notes !== '—') ? notes.trim() : '—';
162	      return `| ${stage.trim()} | ${result.trim()} | ${notesClean} |`;
163	    })
164	  ];
165	
166	  // Follow-up tickets
167	  const followupMatch = body.match(/\*\*Follow-up[^:]*:\*\*\s*(.+)/);
168	  const followup = followupMatch?.[1]?.trim() || 'None';
169	
170	  const statusEmoji = isReady ? '✅' : '🔄';
171	  const metaLine = [
172	    issueNum ? `<${issueUrl}|Issue #${issueNum}>` : null,
173	    prNum    ? `<${prUrl}|PR #${prNum}>` : null,
174	    `*${status}*`,
175	  ].filter(Boolean).join('  ·  ');
176	
177	  const blocks = [
178	    { type: 'header', text: { type: 'plain_text', text: `${statusEmoji} ${title}`, emoji: true } },
179	    {
180	      type: 'section',
181	      text: { type: 'mrkdwn', text: `${metaLine}\n\`wp-media/wp-rocket\`` },
182	      accessory: { type: 'button', text: { type: 'plain_text', text: 'View Comment' }, url: commentUrl }
183	    },
184	    { type: 'divider' },
185	    {
186	      type: 'markdown',
187	      text: tableLines.join('\n') + `\n\n**Follow-up:** ${followup}`
188	    },
189	    { type: 'divider' },
190	  ];
191	
192	  const actions = [];
193	  if (issueNum) actions.push({ type: 'button', text: { type: 'plain_text', text: `Issue #${issueNum}` }, url: issueUrl });
194	  if (prNum)    actions.push({ type: 'button', text: { type: 'plain_text', text: `Pull Request #${prNum}` }, url: prUrl, style: 'primary' });
195	  if (actions.length) blocks.push({ type: 'actions', elements: actions });
196	
197	  return {
198	    text: `${statusEmoji} ${title} · Issue #${issueNum}`,
199	    blocks
200	  };
201	}
