203	// ---------------------------------------------------------------------------
204	// Stage card — compact header + optional detail block
205	// ---------------------------------------------------------------------------
206	
207	function buildStageCard(icon, label, body, num, ghUrl, commentUrl, isIssue, detailFn) {
208	  const refType = isIssue ? 'Issue' : 'PR';
209	  const subtitle = body.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() || label;
210	
211	  const blocks = [
212	    {
213	      type: 'section',
214	      text: { type: 'mrkdwn', text: `${icon}  *${label}*  ·  <${ghUrl}|${refType} #${num}>\n_${subtitle}_` },
215	      accessory: { type: 'button', text: { type: 'plain_text', text: 'View Comment' }, url: commentUrl }
216	    }
217	  ];
218	
219	  // Add a rich detail block if we know how to extract meaningful structure from this comment type
220	  const detail = detailFn ? detailFn(body) : null;
221	  if (detail) blocks.push({ type: 'markdown', text: detail });
222	
223	  blocks.push({
224	    type: 'context',
225	    elements: [{ type: 'mrkdwn', text: `\`wp-media/wp-rocket\`  ·  <${ghUrl}|${refType} #${num}>  ·  <${commentUrl}|Open in GitHub>` }]
226	  });
227	
228	  return { text: `${label} — ${refType} #${num}`, blocks };
229	}
230	
231	// ---------------------------------------------------------------------------
232	// Detail extractors — pull 3-4 structured facts from each comment type
233	// ---------------------------------------------------------------------------
234	
235	function buildGroomingDetail(body) {
236	  const effort     = body.match(/\*\*[Ee]ffort[^:]*:\*\*\s*([^\n,|]+)/)?.[1]?.trim()
237	                  || body.match(/effort[:\s]+([XxSsMmLl]+)/)?.[1]?.trim() || null;
238	  const risk       = body.match(/\*\*[Rr]isk[^:]*:\*\*\s*([^\n,|]+)/)?.[1]?.trim()
239	                  || body.match(/risk[_\s]*level[:\s]+([A-Z]+)/i)?.[1]?.trim() || null;
240	  const confidence = body.match(/\*\*[Cc]onfidence[^:]*:\*\*\s*([^\n,|]+)/)?.[1]?.trim()
241	                  || body.match(/confidence[:\s]+([A-Z]+)/i)?.[1]?.trim() || null;
242	  const openQ      = (body.match(/open[_ ]questions?/gi) || []).length > 0
243	                  ? (body.match(/^\d+\.\s+/gm) || []).length || null
244	                  : null;
245	
246	  const parts = [];
247	  if (effort)     parts.push(`**Effort:** ${effort}`);
248	  if (risk)       parts.push(`**Risk:** ${risk}`);
249	  if (confidence) parts.push(`**Confidence:** ${confidence}`);
250	  const meta = parts.join('  ·  ');
251	
252	  const lines = [meta].filter(Boolean);
253	  if (openQ) lines.push(`**Open questions:** ${openQ} documented, proceeding with assumptions`);
254	
255	  return lines.length ? lines.join('\n') : null;
256	}
257	
258	function buildChallengerDetail(body) {
259	  const verdict = body.match(/\*\*(APPROVED|NEEDS_REVISION|BLOCKED)\*\*/)?.[1]
260	               || (body.toLowerCase().includes('approved') ? 'APPROVED' : null);
261	  const must = (body.match(/MUST_HAVE/g) || []).length;
262	  const should = (body.match(/SHOULD_HAVE/g) || []).length;
263	
264	  const lines = [];
265	  if (verdict) lines.push(`**Verdict:** ${verdict}`);
266	  if (must)    lines.push(`**Must-have findings:** ${must}`);
267	  if (should)  lines.push(`**Should-have findings:** ${should}`);
268	  return lines.length ? lines.join('  ·  ') : null;
269	}
270	
271	function buildReviewDetail(body) {
272	  const verdict  = body.match(/\*\*(PASS|REQUEST_CHANGES|APPROVED)\*\*/)?.[1]
273	                || (body.toLowerCase().includes('approved') ? 'APPROVED'
274	                  : body.toLowerCase().includes('request') ? 'REQUEST_CHANGES' : null);
275	  const critical = (body.match(/CRITICAL/g) || []).length;
276	  const high     = (body.match(/\bHIGH\b/g) || []).length;
277	
278	  const lines = [];
279	  if (verdict)  lines.push(`**Verdict:** ${verdict}`);
280	  if (critical) lines.push(`**Critical blockers:** ${critical}`);
281	  if (high)     lines.push(`**High blockers:** ${high}`);
282	  return lines.length ? lines.join('  ·  ') : null;
283	}
284	
285	function buildQADetail(body) {
286	  // Try to extract AC results as a task list
287	  const acLines = [];
288	  for (const line of body.split('\n')) {
289	    const m = line.match(/AC\d+[^—–-]*[—–-]\s*(.+)/);
290	    if (!m) continue;
291	    const passed = line.includes('PASS') || line.includes('✅');
292	    acLines.push(`- [${passed ? 'x' : ' '}] ${m[1].trim()}`);
293	    if (acLines.length >= 8) break; // cap at 8 items
294	  }
295	  return acLines.length ? acLines.join('\n') : null;
296	}
297	
298	// ---------------------------------------------------------------------------
299	// Generic card — fallback
300	// ---------------------------------------------------------------------------
301	
302	function buildGenericCard(body, num, ghUrl, commentUrl, isIssue) {
303	  const refType = isIssue ? 'Issue' : 'PR';
304	  const title   = body.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() || 'Pipeline Comment';
305	
306	  return {
307	    text: `AI Pipeline · ${refType} #${num}`,
308	    blocks: [
309	      {
310	        type: 'section',
311	        text: { type: 'mrkdwn', text: `🤖  *${title}*\n<${ghUrl}|${refType} #${num}> · \`wp-media/wp-rocket\`` },
312	        accessory: { type: 'button', text: { type: 'plain_text', text: 'View Comment' }, url: commentUrl }
313	      },
314	      { type: 'context', elements: [{ type: 'mrkdwn', text: `<${commentUrl}|View on GitHub>` }] }
315	    ]
316	  };
317	}
318	
319	// ---------------------------------------------------------------------------
320	// Markdown table parser
321	// ---------------------------------------------------------------------------
322	
323	function parseMarkdownTable(body) {
324	  const rows = [];
325	  for (const line of body.split('\n')) {
326	    if (!line.startsWith('|')) continue;
327	    if (/^\|[\s\-:|]+\|$/.test(line)) continue;
328	    const cells = line.split('|').slice(1, -1).map(c => c.trim());
329	    if (cells[0]?.toLowerCase() === 'stage') continue;
330	    if (cells.length >= 2) rows.push(cells);
331	  }
332	  return rows;
333	}
334	
335	// ---------------------------------------------------------------------------
336	// Extract issue number from PR comment body text
337	// ---------------------------------------------------------------------------
338	
339	function extractIssueFromBody(body) {
340	  return body.match(/[Ii]ssue\s*[:#]?\s*#?(\d+)/)?.[1] || null;
341	}
342	
343	// ---------------------------------------------------------------------------
344	// Thread persistence — one Slack thread per GitHub issue
345	// ---------------------------------------------------------------------------
346	
347	function getThreadTs(issueNum) {
348	  try { return fs.readFileSync(path.join(THREADS_DIR, `issue-${issueNum}.ts`), 'utf8').trim(); }
349	  catch { return null; }
350	}
351	
352	function saveThreadTs(issueNum, ts) {
353	  try {
354	    fs.mkdirSync(THREADS_DIR, { recursive: true });
355	    fs.writeFileSync(path.join(THREADS_DIR, `issue-${issueNum}.ts`), ts);
356	  } catch (e) {
357	    process.stderr.write(`slack-notify: could not save thread ts: ${e.message}\n`);
358	  }
359	}
360	
361	// ---------------------------------------------------------------------------
362	// Tool output extraction
363	// ---------------------------------------------------------------------------
364	
365	function getOutput(data) {
366	  const content = data.tool_response?.content;
367	  if (Array.isArray(content)) return content.map(c => c.text || '').join('');
368	  return data.tool_response?.output || data.tool_result?.output || '';
369	}
370	
371	// ---------------------------------------------------------------------------
372	// Body extraction from raw bash command (heredoc / double-quoted / single-quoted)
373	// ---------------------------------------------------------------------------
374	
375	function extractBody(command) {
376	  let m = command.match(/(?:--body|-b)\s+"?\$\(cat\s+<<['"]?(\w+)['"]?\n([\s\S]*?)\n\1/);
377	  if (m) return m[2].trim();
378	
379	  m = command.match(/(?:--body|-b)\s+"((?:[^"\\]|\\.)*)"/s);
380	  if (m && !m[1].trimStart().startsWith('$(')) {
381	    return m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"').trim();
382	  }
383	
384	  m = command.match(/(?:--body|-b)\s+'((?:[^'\\]|\\.)*)'/s);
385	  if (m) return m[1].trim();
386	
387	  return '';
388	}
389	
390	// ---------------------------------------------------------------------------
391	// Slack API — returns ts on success (used for threading)
392	// ---------------------------------------------------------------------------
393	
394	async function postToSlack(payload) {
395	  const body = JSON.stringify(payload);
396	  return new Promise(resolve => {
397	    const req = https.request(
398	      {
399	        hostname: 'slack.com',
400	        path:     '/api/chat.postMessage',
401	        method:   'POST',
402	        headers:  {
403	          'Content-Type':   'application/json',
404	          'Authorization':  `Bearer ${SLACK_TOKEN}`,
405	          'Content-Length': Buffer.byteLength(body)
406	        }
407	      },
408	      res => {
409	        let respData = '';
410	        res.on('data', d => { respData += d; });
411	        res.on('end', () => {
412	          try {
413	            const resp = JSON.parse(respData);
414	            if (!resp.ok) {
415	              process.stderr.write(`slack-notify: Slack API error: ${resp.error}\n`);
416	              resolve(null);
417	            } else {
418	              resolve(resp.ts || null);
419	            }
420	          } catch (e) {
421	            process.stderr.write(`slack-notify: response parse error: ${e.message}\n`);
422	            resolve(null);
423	          }
424	        });
425	      }
426	    );
427	    req.on('error', e => { process.stderr.write(`slack-notify: network error: ${e.message}\n`); resolve(null); });
428	    req.setTimeout(8000, () => { req.destroy(); resolve(null); });
429	    req.write(body);
430	    req.end();
431	  });
432	}
